import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"64、【未济】 坎下离上","description":"周易尚氏学 - 64、【未济】 坎下离上","frontmatter":{"title":"64、【未济】 坎下离上","description":"周易尚氏学 - 64、【未济】 坎下离上"},"headers":[],"relativePath":"zh/classics/shangshi/069.md","filePath":"zh/classics/shangshi/069.md"}'),h={name:"zh/classics/shangshi/069.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_64、【未济】-坎下离上" tabindex="-1">64、【未济】 坎下离上 <a class="header-anchor" href="#_64、【未济】-坎下离上" aria-label="Permalink to “64、【未济】 坎下离上”">​</a></h1><p>济止也。六爻皆当位。止其所而不动。故曰既济。兹六交皆不当位。不止。故曰未济。终而止。则其道穷。终而不止。则其道不穷。故既未济相续而循环。柔得五中故亨。艮为小孤。卦有三艮形。故易林涣之未济云。三虎上山。更相喧唤。是以未济为三艮。故曰三虎上山。兹曰小狐。是以艮为狐。讫说文涸也。乾宝云。小狐力弱。讫乃可济今水未涸。故儒其尾。艮为尾也。濡尾故无攸利。按九家坎亦为狐。兹曰小狐曰尾。艮为小为尾。故知取艮象。济者济坎水也。</p><p>彖曰。未济宁。柔得中也。小狐讫济。未出中也。濡其尾无攸利。不续终也。虽不当位。刚柔应也。</p><p>未出中。言二陷于坎中也。六爻皆不当位。无攸利。然赐柔相应。穷则宜变。变则通。故不续终。申不止之义也。</p><p>象曰。火在水上。未济。君子以慎辨物居方。</p><p>乾阳物。坤阴物。阴阳各当位。是居方也。阴阳皆不当位。是聚而失其方也。辨而明之。慎其居而择所处。则无咎矣。故君子以之。</p><p>初六。濡其尾。吝。</p><p>在下故曰尾。濡尾故吝。</p><h3 id="象曰。濡其尾。亦不知极也。" tabindex="-1">象曰。濡其尾。亦不知极也。 <a class="header-anchor" href="#象曰。濡其尾。亦不知极也。" aria-label="Permalink to “象曰。濡其尾。亦不知极也。”">​</a></h3><p>极说文栋也。栋居屋中。故极者中也。濡尾知极。言初在下失中。</p><p>九二。曳春轮。贞吉。</p><p>坎为轮为曳。居中。故贞吉。</p><h3 id="象曰。九二贞吉。中以行正也。" tabindex="-1">象曰。九二贞吉。中以行正也。 <a class="header-anchor" href="#象曰。九二贞吉。中以行正也。" aria-label="Permalink to “象曰。九二贞吉。中以行正也。”">​</a></h3><p>以位言。九二中而不正。兹曰行正。以正释贞也。非谓位正。</p><p>六三。未济征凶。利涉大川。</p><p>不当位。前遇险。故征凶。征凶则不能利涉。兹日利涉大川。上下文义反背。朱子疑利上有不字。按象云位不当。则不利也。缺以俟知者。</p><h3 id="象曰。未济征凶。" tabindex="-1">象曰。未济征凶。 <a class="header-anchor" href="#象曰。未济征凶。" aria-label="Permalink to “象曰。未济征凶。”">​</a></h3><p>位不当也承乘皆险。动则必凶。柔居刚。故位不当。</p><p>九四。贞吉。悔亡。震用伐克方。三年有赏于大国。</p><p>坎为鬼。易林观之既济云。班马还师。是用半震。震为马为反。既济三半震。故曰班马还师。兹易曰震用伐鬼方。亦以四五形震。为易林之所本。震为威武为征伐。坎为三故曰三年。有赏于大国者。言伐鬼方有功。以大国赏之也。盖以五上半艮为国也。贞吉卜问吉也。高士奇天禄识余云。易震用伐鬼方。敦深谓震乃挚伯名。程传训为威武。则三年有赏于大国。何人也。以文理言。此说颇胜。而述之者少。</p><h3 id="象曰。贞吉悔亡。志行也。" tabindex="-1">象曰。贞吉悔亡。志行也。 <a class="header-anchor" href="#象曰。贞吉悔亡。志行也。" aria-label="Permalink to “象曰。贞吉悔亡。志行也。”">​</a></h3><p>坎为志。四承乘皆阴。故志行。</p><p>六五。贞吉。无悔。君子之光。</p><p>有孚吉。离为光。五君位。故君子之光。下有应。故有孚吉。</p><h3 id="象曰。君子之光。其晖吉也。" tabindex="-1">象曰。君子之光。其晖吉也。 <a class="header-anchor" href="#象曰。君子之光。其晖吉也。" aria-label="Permalink to “象曰。君子之光。其晖吉也。”">​</a></h3><p>离为大明。故其晖吉。晖。说文光也。</p><p>上九。有孚于饮酒。无咎。濡其首。有孚失是。</p><p>坎为酒。为饮食。上九下履重坎。故有孚于饮酒。有应故无咎。上应在三。三居重坎之中。故亦濡其首。六爻皆有应。故有孚。皆失位。故失是。然不续终之故。正以此也。</p><h3 id="象曰。饮酒濡首。亦不知节也。" tabindex="-1">象曰。饮酒濡首。亦不知节也。 <a class="header-anchor" href="#象曰。饮酒濡首。亦不知节也。" aria-label="Permalink to “象曰。饮酒濡首。亦不知节也。”">​</a></h3><p>上艮为节。节止也。过而不止。故不知节。</p><p>附</p><p>即未济之卦形。即异于常卦。故所取之象。往往为本卦所无。如曰逐。曰高宗。曰伐。日襦（左系）衣如（左衣）。曰杀。曰祭。曰福。曰大国。曰震。本卦皆无此象。于是虞氏用卦变以求其象。惝恍支离。莫可究洁。然经于九四曰震。且明以四五为震矣。故知其它皆用半象也。易林本之。于观之既济云。班马还师。震之即济云。齿齿（右间）齿齿（上契无大）。兑之既济云。积石为山。旅之既济云。逐鹿南山。恒之既济云。三妪治民。是皆于既济取震马震鹿巽妪兑齿艮山象。又谦之未济。千柱百梁。是以艮为梁柱。未济三艮形。故曰千柱百梁。又涣之未济。三虎上山。亦以三艮为三虎。又蹇之未济云。一口三舌。亦以重兑为三舌。凡易林取象。无不本于易。此用半象。必有所受之。而其详不传。由是证施孟梁丘三家易学。其取象皆尚有极繁琐之口传。徒以古人尚质。竹书艰难。其所为易传。皆疏其大义。而不详其烦琐。致使象数之细微。皆存之口授。不着竹帛。以伤其方雅。故汉时学易者必有师。非重师。重口授也。口授一绝。后人虽欲知而莫由。幸焦氏易林未亡。吾人可按其辞。抽绎坠象。使易之晦辞。得以复明。易之误解。俾以复正。不然且终古长夜矣。上经终坎离。坎中爻震艮。离中爻巽兑。是举坎离而六子具也。下经终既未济。乾坤具备。而即济一阳一阴。则震兑也。未济一阴一阳。则艮巽也。是举坎离而八卦备也。故以为六十四卦之殿。其卦既无所不包。其象遂父母与六子俱备。故易与易林。于既未济取象。独不同欤。</p>',32)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
